import { readFileSync } from "node:fs";
import type { CarrierCode, Iata } from "./types.js";

/**
 * Airport and airline code tables, generated by `npm run build-codes`
 * (see scripts/build-codes.ts and src/data/README.md).
 */
const load = <T>(file: string): T => JSON.parse(readFileSync(new URL(`./data/${file}`, import.meta.url), "utf8")) as T;

/** IATA airport code → [ICAO code, IANA zone]. */
const AIRPORTS = load<Record<Iata, [icao: string, zone: string]>>("airports.json");
/** ICAO airline designator (callsign prefix) → IATA airline code. */
const AIRLINES = load<Record<string, CarrierCode>>("airlines.json");

const IATA_BY_ICAO = new Map(Object.entries(AIRPORTS).map(([iata, [icao]]) => [icao, iata]));

export type ZoneLookup = (station: Iata) => string;

export class UnknownStationError extends Error {
  constructor(public readonly station: Iata) {
    super(`Unknown station ${station}. Is it a valid 3-letter IATA airport code?`);
  }
}

function lookup(station: Iata): [string, string] {
  const entry = AIRPORTS[station.toUpperCase()];
  if (!entry) throw new UnknownStationError(station);
  return entry;
}

/** IANA time zone of a station. */
export const zoneFor: ZoneLookup = (station) => lookup(station)[1];

/** ICAO code of a station, e.g. LHR → EGLL. */
export const icaoFor = (station: Iata): string => lookup(station)[0];

/** IATA code of an ICAO airport, if it has one. */
export const iataForAirport = (icao: string): Iata | undefined => IATA_BY_ICAO.get(icao.toUpperCase());

/** IATA airline code for an ICAO designator (callsign prefix), e.g. BAW → BA. */
export const iataForAirline = (icao: string): CarrierCode | undefined => AIRLINES[icao.toUpperCase()];

const KNOWN_CARRIERS = new Set(Object.values(AIRLINES));

/** Whether any ICAO designator maps to this IATA airline code. */
export const hasAirlineDesignator = (carrier: CarrierCode): boolean => KNOWN_CARRIERS.has(carrier.toUpperCase());
